from fractions import Fraction as F
import json
rows=[('A',15,{'T':1,'U':0,'V':0,'W':1}),('A',9,{'T':0,'U':1,'V':1,'W':1}),('B',6,{'T':1,'U':0,'V':0,'W':0}),('B',5,{'T':0,'U':1,'V':0,'W':0}),('C',9,{'T':1,'U':1,'V':1,'W':1}),('C',5,{'T':0,'U':1,'V':1,'W':0}),('D',14,{'T':0,'U':0,'V':0,'W':0}),('D',9,{'T':1,'U':1,'V':1,'W':0})]
L={'A':[0,24,11,6],'B':[19,0,19,8],'C':[9,10,0,16],'D':[21,24,20,0]}
s=[r for r in rows if r[2]['V']==0]
z=sum(r[1] for r in s)
def losses(rs):
    total=sum(r[1] for r in rs)
    return {a:sum(F(r[1]*v['ABCD'.index(r[0])],total) for r in rs) for a,v in L.items()}
p={a:float(F(sum(r[1] for r in s if r[0]==a),z)) for a in 'ABCD'}
remaining=losses(s)
branches={}
for t,c in [('T',F(8,10)),('U',F(12,10)),('W',F(74,10))]:
    val=c
    branches[t]={}
    for b in (0,1):
        sub=[r for r in s if r[2][t]==b]
        if not sub:
            branches[t][str(b)]='IMPOSSIBLE'
            continue
        ls=losses(sub)
        a=min(ls,key=ls.get)
        branches[t][str(b)]=a
        val+=F(sum(r[1] for r in sub),z)*ls[a]
    remaining[t]=val
a=min(remaining,key=remaining.get)
result={'posterior':p,'remaining_losses':{k:float(v) for k,v in remaining.items()},'action':a,'repair_after':branches.get(a,{})}
payload=json.dumps(result)
recovered=json.loads(payload)
# Independent hand-aggregated checks: V=0 weights A15 B11 D14 (total40).
assert recovered['posterior']=={'A':.375,'B':.275,'C':0.,'D':.35}
expected={'A':348/40,'B':397/40,'C':469/40,'D':579/40,'T':.8+(144+120)/40,'U':1.2+228/40,'W':7.4+112/40}
assert all(abs(recovered['remaining_losses'][k]-v)<1e-10 for k,v in expected.items())
assert recovered['action']=='T' and recovered['repair_after']=={'0':'B','1':'A'}
print(payload)
print('Independent aggregate checks passed.')

